para.programlisting:
clf();
n = 100;
t = datetime(2020, 1, 1) + caldays(1:n)';

// Temperature, pressure and humidity
temperature = 15 + 8 * sin((1:n)' / 15) + rand(n, 1);
pressure = 1010 + 10 * sin((1:n)' / 20) + rand(n, 1);
humidity = 60 + 15 * cos((1:n)' / 18) + rand(n, 1);

ts = timeseries(t, temperature, pressure, humidity, ..
    "VariableNames", ["Time", "Temperature", "Pressure", "Humidity"]);
f = gcf();
f.axes_size = [1200; 600];
subplot(1, 2, 1);
plot(1:n, temperature);
title("Temperature");

subplot(1, 2, 2);
a = stackedplot(ts, "Title", "Weather data");
mean_values = [mean(humidity), mean(pressure), mean(temperature)];
x = gce().children.data(:,1);
x_ticks = gca().x_ticks;
for i = 3:-1:1
    plot(a(i), x, mean_values(i) * ones(1,n), "r");
    legend([ts.Properties.VariableNames(3-i+2); "Mean"])
    if i == 1 then
        a(i).x_ticks = x_ticks;
    else
        a(i).axes_visible(1) = "off";
    end
end

